package octal

import "errors"

// ParseOctal converts an octal number, represented as a string (e.g.
// '1735263'), to its decimal equivalent.
//
// The conversion is done from first principles: each digit is a linear
// combination of powers of 8, evaluated left to right (Horner's method):
//
//	value = value*8 + digit
//
// which is equivalent to summing digit * 8^(n-1-i) for every digit.
// Any input containing a character that is not an octal digit (0-7),
// including the empty string, is invalid and is treated as octal 0,
// with a non-nil error returned.
func ParseOctal(input string) (int64, error) {
	if input == "" {
		return 0, errors.New("empty input is not a valid octal number")
	}

	var value int64
	for i := 0; i < len(input); i++ {
		digit := int64(input[i] - '0')
		if digit < 0 || digit > 7 {
			return 0, errors.New("invalid octal digit")
		}
		value = value*8 + digit
	}
	return value, nil
}

